  const handleFetchDecisionTrace = async (caseIdToTrace?: string) => {
    const id = caseIdToTrace || decisionTraceCaseId;
    if (!id.trim()) {
      setDecisionTraceError("Please enter a valid Recovery Case UUID.");
      return;
    }
    setDecisionTraceLoading(true);
    setDecisionTraceError(null);
    try {
      const trace = await fetchDecisionTrace(id.trim());
      setDecisionTraceData(trace);
    } catch (err) {
      setDecisionTraceError(err instanceof Error ? err.message : "Failed to load decision trace");
      setDecisionTraceData(null);
    } finally {
      setDecisionTraceLoading(false);
    }
  };

  const handleRevokeTokenSubmit = async () => {
    if (!revokeJtiInput.trim()) return;
    setRevokeLoading(true);
    setError(null);
    try {
      const res = await revokeToken(revokeJtiInput.trim(), revokeReasonInput || undefined);
      setRevokeModalOpen(false);
      setRevokeSuccessMsg(`Token JTI "${res.jti}" successfully revoked and blacklisted. (Zero financial mutations executed)`);
      setRevokeJtiInput("");
      setRevokeReasonInput("");
      const [tcRes, evRes] = await Promise.all([
        fetchTrustCenterOverview().catch(() => null),
        fetchSecurityEvents(1, 50, securitySeverityFilter, securityEventTypeFilter).catch(() => null),
      ]);
      setTrustCenterData(tcRes);
      setSecurityEventsData(evRes);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to revoke token");
    } finally {
      setRevokeLoading(false);
    }
  };

