  const formatPct = (val: number | null) =>
    val !== null ? `${(val * 100).toFixed(1)}%` : "—";
  const formatNum = (val: number | null, decimals = 2) =>
    val !== null ? val.toFixed(decimals) : "—";
  const formatDelta = (val: number | null, isPct = true) => {
    if (val === null) return "—";
    const prefix = val > 0 ? "+" : "";
    return isPct ? `${prefix}${(val * 100).toFixed(1)}%` : `${prefix}${val.toFixed(3)}`;
  };

